
-- Drop old constraint, add richer columns, reload all 330 tables
ALTER TABLE schema_table_registry
  DROP CONSTRAINT IF EXISTS schema_table_registry_table_group_check,
  ADD COLUMN IF NOT EXISTS purpose TEXT,
  ADD COLUMN IF NOT EXISTS layer VARCHAR(16),
  ADD COLUMN IF NOT EXISTS engine_family VARCHAR(64),
  ADD COLUMN IF NOT EXISTS source VARCHAR(64) DEFAULT 'manus_schema_ts',
  ADD COLUMN IF NOT EXISTS created_at BIGINT DEFAULT 0;

ALTER TABLE schema_table_registry
  ALTER COLUMN table_group TYPE TEXT;

TRUNCATE schema_table_registry;


